import csv
from collections import defaultdict

csv_path = "/workspace/rq1.csv"
benchmarks = ["NPEX", "BugSwarm", "Defects4J", "Genesis", "Bears"]
tools = ["evosuite", "npetest"]

def compute(threshold):
    counts = defaultdict(lambda: {t: 0 for t in tools})
    with open(csv_path, newline='') as f:
        reader = csv.DictReader(f)
        for row in reader:
            bench = (row.get("a") or "").strip()
            proj = (row.get("b") or "").strip()
            if bench not in benchmarks or not proj:
                continue
            for t in tools:
                val = (row.get(t) or "").strip()
                if not val:
                    continue
                try:
                    if float(val) >= threshold:
                        counts[bench][t] += 1
                except ValueError:
                    pass
    totals = {t: 0 for t in tools}
    for b in benchmarks:
        for t in tools:
            totals[t] += counts[b][t]
    return counts, totals

for thr in (0.0, 50.0):
    counts, totals = compute(thr)
    print(f"=== Threshold >= {thr} ===")
    print("Benchmark,EvoSuite,NPETest")
    for b in benchmarks:
        print(f"{b},{counts[b]['evosuite']},{counts[b]['npetest']}")
    print(f"Total,{totals['evosuite']},{totals['npetest']}")
    print()
